 auto* top=new QHBoxLayout;auto* brand=new QLabel("D-MASH");brand->setObjectName("wordmark");top->addWidget(brand);top->addStretch();account_=new QLabel(tr("Your conversations, on your devices"));account_->setObjectName("accountName");account_->setTextFormat(Qt::PlainText);top->addWidget(account_);login_=new QPushButton(tr("Sign in"));login_->setObjectName("login");login_->setEnabled(false);logout_=new QPushButton(tr("Sign out"));logout_->setObjectName("logout");logout_->hide();auto* about=new QPushButton(tr("Application details"));about->setObjectName("about");cancel_=new QPushButton(tr("Cancel"));cancel_->setObjectName("cancelWork");cancel_->hide();top->addWidget(login_);top->addWidget(logout_);top->addWidget(cancel_);top->addWidget(about);layout->addLayout(top);
 auto* network=new QHBoxLayout;status_=new QLabel(tr("Node service not attached"));status_->setObjectName("nodeStatus");status_->setTextFormat(Qt::PlainText);status_->setWordWrap(true);network->addWidget(status_,1);nodeToggle_=new QPushButton(tr("Start Node"));nodeToggle_->setObjectName("nodeToggle");nodeToggle_->setEnabled(false);nodeSettings_=new QPushButton(tr("Connections"));nodeSettings_->setObjectName("nodeSettings");nodeSettings_->setEnabled(false);network->addWidget(nodeToggle_);network->addWidget(nodeSettings_);refresh_=new QPushButton(tr("Refresh Node status"));refresh_->setObjectName("refresh");refresh_->setEnabled(false);detach_=new QPushButton(tr("Detach UI"));detach_->setObjectName("detach");detach_->setEnabled(false);network->addWidget(refresh_);network->addWidget(detach_);layout->addLayout(network);
 auto* split=new QSplitter;auto* sidebar=new QWidget;auto* side=new QVBoxLayout(sidebar);side->setContentsMargins(0,0,8,0);auto* title=new QLabel(tr("Conversations"));title->setStyleSheet("font-weight:600;padding:8px");side->addWidget(title);chats_=new QListWidget;chats_->setObjectName("chats");chats_->setAccessibleName(tr("Conversations"));chats_->setEnabled(false);side->addWidget(chats_,1);import_=new QPushButton(tr("Import existing profile"));import_->setObjectName("import");import_->setEnabled(false);side->addWidget(import_);create_=new QPushButton(tr("Create profile"));create_->setObjectName("create");create_->setEnabled(false);side->addWidget(create_);split->addWidget(sidebar);
 auto* pane=new QWidget;auto* chat=new QVBoxLayout(pane);chat->setContentsMargins(14,0,0,0);chatTitle_=new QLabel(tr("Welcome to D-MASH"));chatTitle_->setObjectName("chatTitle");chatTitle_->setTextFormat(Qt::PlainText);chat->addWidget(chatTitle_);notice_=new QLabel(tr("Create a profile or import your existing conversations."));notice_->setObjectName("notice");notice_->setWordWrap(true);notice_->setTextFormat(Qt::PlainText);chat->addWidget(notice_);history_=new MessageHistory;history_->setObjectName("history");chat->addWidget(history_,1);compose_=new QTextEdit;compose_->setObjectName("compose");compose_->setAccessibleName(tr("Message"));compose_->setPlaceholderText(tr("Write a message…"));compose_->setMaximumHeight(100);compose_->setEnabled(false);chat->addWidget(compose_);auto* actions=new QHBoxLayout;actions->addStretch();send_=new QPushButton(tr("Send"));send_->setObjectName("send");send_->setEnabled(false);actions->addWidget(send_);chat->addLayout(actions);split->addWidget(pane);split->setSizes({280,760});split->setStretchFactor(1,3);layout->addWidget(split,1);
